"use client"

import type { ReactNode } from "react"
import { Bar, BarChart, CartesianGrid, LabelList, XAxis, YAxis } from "recharts"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/serigraph/ui/card"
import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/serigraph/ui/chart"

// The dashboard's figures and charts, usable on their own: a headline figure in the mono face on the canvas, a
// panel (a plane with a title and one line on what it shows), visitors per night as stacked bars (booked ahead flat,
// at the door stippled) and seats sold by kind of session as level bars, one fill each. Series colours are roles
// that differ from the plane beneath in every colourway, and the fills tell them apart in grey as well.

// A fixed locale, so the server and every browser print the same digits.
const number = new Intl.NumberFormat("en-GB")
export const count = (n: number) => number.format(n)

/** A headline figure on the canvas: what it counts in the capitals, the figure in mono, one line of context. */
export function Figure({
  label,
  value,
  note,
}: {
  label: string
  value: string
  note: string
}) {
  return (
    <div className="@container/figure min-w-0">
      <p className="m-0 caps text-(--text)">{label}</p>
      <p className="m-0 mt-hair font-mono text-h2 leading-h2 text-(--text) tabular-nums @min-[11rem]/figure:text-h1 @min-[11rem]/figure:leading-h1">
        {value}
      </p>
      <p className="m-0 text-small leading-small">{note}</p>
    </div>
  )
}

/** A section of the dashboard on a plane: its title, one line on what it shows, then the chart. */
export function Panel({
  title,
  note,
  children,
  className,
}: {
  title: string
  note: string
  children: ReactNode
  className?: string
}) {
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>
          <h2 className="m-0 font-[inherit] text-[length:inherit] leading-[inherit]">
            {title}
          </h2>
        </CardTitle>
        <CardDescription>{note}</CardDescription>
      </CardHeader>
      <CardContent>{children}</CardContent>
    </Card>
  )
}

export interface VisitorNight {
  /** The axis label: "Thu 29". */
  night: string
  ahead: number
  door: number
}

const visitorsConfig = {
  ahead: { label: "Booked ahead", color: "var(--action)", fill: "flat" },
  door: { label: "At the door", color: "var(--tone-2)", fill: "stipple" },
} satisfies ChartConfig

/** Visitors per night: those who booked ahead in the action colour, those who came to the door stippled above. */
export function VisitorsChart({ nights }: { nights: VisitorNight[] }) {
  return (
    <ChartContainer config={visitorsConfig} className="aspect-auto h-64 w-full">
      <BarChart
        accessibilityLayer
        data={nights}
        margin={{ top: 8, right: 4, bottom: 0, left: 0 }}
      >
        <CartesianGrid vertical={false} />
        <XAxis
          dataKey="night"
          tickLine={false}
          tickMargin={8}
          // The mono face is wider than the one Recharts measures with, so leave the labels room.
          minTickGap={12}
          interval="preserveStartEnd"
        />
        <YAxis
          tickLine={false}
          axisLine={false}
          width={36}
          allowDecimals={false}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <ChartLegend content={<ChartLegendContent />} />
        <Bar dataKey="ahead" stackId="night" fill="var(--color-ahead)" />
        <Bar dataKey="door" stackId="night" fill="var(--color-door)" />
      </BarChart>
    </ChartContainer>
  )
}

export type SessionKind = "show" | "talk" | "telescope"

export interface KindSeats {
  kind: SessionKind
  /** The axis label: "Dome shows". */
  label: string
  sold: number
}

const kindsConfig = {
  show: { label: "Dome shows", color: "var(--action)", fill: "flat" },
  talk: { label: "Talks", color: "var(--tone-2)", fill: "stipple" },
  telescope: { label: "Telescope", color: "var(--tone-3)", fill: "louvers" },
} satisfies ChartConfig

/** The kind's name above the left end of its bar, in the reading face. */
function KindName(props: {
  x?: number | string
  y?: number | string
  value?: unknown
}) {
  return (
    <text
      x={Number(props.x)}
      y={Number(props.y) - 8}
      className="font-read text-body"
      fill="var(--text, var(--ink))"
    >
      {String(props.value)}
    </text>
  )
}

/** Seats sold by kind of session: one level bar each under its name, in its own fill, the figure at its end. */
export function SeatsByKindChart({ kinds }: { kinds: KindSeats[] }) {
  return (
    <ChartContainer
      config={kindsConfig}
      className="aspect-auto w-full"
      style={{ height: `${kinds.length * 4.25}rem` }}
    >
      <BarChart
        accessibilityLayer
        // Each bar takes its kind's colour from its row, and with it the kind's fill (ChartStyle).
        data={kinds.map((k) => ({ ...k, fill: `var(--color-${k.kind})` }))}
        layout="vertical"
        barSize={22}
        margin={{ top: 24, right: 56, bottom: 0, left: 0 }}
      >
        <XAxis type="number" hide />
        <YAxis type="category" dataKey="label" hide />
        <ChartTooltip
          cursor={false}
          content={<ChartTooltipContent hideLabel nameKey="kind" />}
        />
        <Bar dataKey="sold" name="Seats sold" isAnimationActive={false}>
          <LabelList dataKey="label" content={KindName} />
          <LabelList
            dataKey="sold"
            position="right"
            offset={8}
            formatter={(value: unknown) =>
              typeof value === "number" ? count(value) : String(value)
            }
          />
        </Bar>
      </BarChart>
    </ChartContainer>
  )
}

"use client"

import { Avatar, AvatarFallback } from "@/serigraph/ui/avatar"
import { Badge } from "@/serigraph/ui/badge"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/serigraph/ui/table"
import { count } from "@/serigraph/blocks/dashboard-01-charts"

// The dashboard's lists, usable on their own: tonight's sessions as a ledger on the canvas, and the bookings coming
// up as an open list between fine lines.

export interface TonightSession {
  id: string
  /** Start and end, 24-hour. */
  starts: string
  ends: string
  title: string
  place: string
  host: string
  seats: number
  taken: number
}

/** Seats left as a badge: "Full" in outline, otherwise how many in the highlight. */
function SeatsLeft({ session }: { session: TonightSession }) {
  const left = Math.max(0, session.seats - session.taken)
  return left === 0 ? (
    <Badge variant="outline">Full</Badge>
  ) : (
    <Badge>{count(left)} left</Badge>
  )
}

/**
 * Tonight's sessions: when in mono, what and where, seats taken of seats. In a table narrower than 30rem (a phone)
 * the place moves under the title and the badge under the seats, so no column is squeezed to a word a line.
 */
export function TonightTable({ sessions }: { sessions: TonightSession[] }) {
  if (!sessions.length)
    return <p className="m-0 text-body leading-body">No sessions tonight.</p>
  return (
    <div className="@container/tonight">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead className="ps-0">Time</TableHead>
            <TableHead>Session</TableHead>
            <TableHead className="@max-[30rem]/tonight:hidden">Place</TableHead>
            <TableHead className="text-end">Seats</TableHead>
            <TableHead className="pe-0 @max-[30rem]/tonight:hidden">
              <span className="sr-only">Left</span>
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {sessions.map((s) => (
            <TableRow key={s.id}>
              <TableCell className="ps-0 align-top font-mono text-small">
                {s.starts}
                <span className="block">{s.ends}</span>
              </TableCell>
              <TableCell className="align-top whitespace-normal">
                {s.title}
                <span className="block text-small leading-small">
                  {s.host}
                  <span className="@min-[30rem]/tonight:hidden">
                    {" "}
                    · {s.place}
                  </span>
                </span>
              </TableCell>
              <TableCell className="align-top @max-[30rem]/tonight:hidden">
                {s.place}
              </TableCell>
              <TableCell className="text-end align-top font-mono text-small">
                {count(s.taken)}
                <span> / {count(s.seats)}</span>
                <span className="mt-hair block @min-[30rem]/tonight:hidden">
                  <SeatsLeft session={s} />
                </span>
              </TableCell>
              <TableCell className="pe-0 text-end align-top @max-[30rem]/tonight:hidden">
                <SeatsLeft session={s} />
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

export interface Booking {
  id: string
  /** Who booked: a person, a school, a society. */
  who: string
  /** What they booked: "The sky tonight". */
  session: string
  /** When, short: "Fri 6 Nov, 10:00". */
  when: string
  seats: number
}

const initials = (name: string) =>
  name
    .split(/\s+/u)
    .filter((word) => /^\p{Lu}/u.test(word))
    .slice(0, 2)
    .map((word) => word[0])
    .join("")

/** Bookings coming up, between fine lines: who in a tone circle, what and when, and how many seats in mono. */
export function UpcomingBookings({ bookings }: { bookings: Booking[] }) {
  if (!bookings.length)
    return <p className="m-0 text-body leading-body">Nothing booked ahead.</p>
  return (
    <ul className="m-0 list-none p-0">
      {bookings.map((b, i) => (
        <li
          key={b.id}
          className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-start gap-x-tight border-[var(--edge)] py-tight not-last:border-b-(length:--line)"
        >
          <Avatar data-tone={String((i % 4) + 1)} className="mt-0.5">
            <AvatarFallback>{initials(b.who)}</AvatarFallback>
          </Avatar>
          <span className="min-w-0">
            <span className="block leading-ui font-semibold">{b.who}</span>
            <span className="mt-1 block text-small leading-small">
              {b.session}
              <span className="block">{b.when}</span>
            </span>
          </span>
          <span className="pt-0.5 font-mono text-small whitespace-nowrap">
            {count(b.seats)} {b.seats === 1 ? "seat" : "seats"}
          </span>
        </li>
      ))}
    </ul>
  )
}

"use client"

import { cn } from "@/serigraph/lib/utils"
import {
  Figure,
  Panel,
  SeatsByKindChart,
  VisitorsChart,
  type KindSeats,
  type VisitorNight,
} from "@/serigraph/blocks/dashboard-01-charts"
import {
  TonightTable,
  UpcomingBookings,
  type Booking,
  type TonightSession,
} from "@/serigraph/blocks/dashboard-01-lists"

// The observatory's week at a glance: four figures in mono on the canvas, visitors per night and seats sold by kind
// of session on planes, tonight's sessions as a ledger and the bookings coming up. Pass your own data, shaped like
// SAMPLE; the layout follows the width of its container, so it works beside a sidebar as well as on a whole page.

export const meta = {
  title: "Dashboard",
  description:
    "The observatory's week: four figures in mono, visitors per night and seats by kind of session in Serigraph's fills, tonight's sessions and the bookings ahead.",
}

export interface Dashboard01Data {
  /** The period the figures cover, under the title. */
  period: string
  figures: { label: string; value: string; note: string }[]
  visitors: { title: string; note: string; nights: VisitorNight[] }
  kinds: { title: string; note: string; rows: KindSeats[] }
  tonight: { title: string; note: string; rows: TonightSession[] }
  bookings: { title: string; note: string; rows: Booking[] }
}

